  <section id="settings-rights" class="panel settings-section"><div class="section-heading"><div><span class="eyebrow">Пофамильно</span><h2>Роли и права</h2></div></div><form id="rightsForm"><div class="table-wrap"><table class="rights-table"><thead><tr><th>Сотрудник</th><th>Роль</th><th>Запасной</th>${[["rooms","Залы"],["analytics","Аналитика"],["news","Новости"],["employees_admin","Сотрудники"],["settings","Настройки"],["rates","Ставки"]].map(([,l])=>`<th>${l}</th>`).join("")}</tr></thead><tbody>${state.employees.filter(e=>!e.archived).map(e=>`<tr><td><strong>${esc(e.name)}</strong><small>${esc(e.department)}</small></td><td><select name="role_${e.id}" ${editable?"":"disabled"}>${Object.entries(roleLabels).map(([v,l])=>`<option value="${v}" ${e.role===v?"selected":""}>${l}</option>`).join("")}</select></td><td><select name="substitute_${e.id}" ${editable?"":"disabled"}><option value="">Автоподбор</option>${employeeOptions(e.substitute?[e.substitute]:[],[e.id])}</select></td>${features.map(feature=>`<td><input type="checkbox" name="${feature}_${e.id}" ${can(feature,e)?"checked":""} ${editable?"":"disabled"} aria-label="${feature}: ${esc(e.name)}"></td>`).join("")}</tr>`).join("")}</tbody></table></div><div class="form-actions"><button class="button" ${editable?"":"disabled"}>Сохранить права</button></div></form>${editable?"":`<p class="muted">Изменять роли и права может только директор или администратор портала.</p>`}</section>
