function analyticsBounds(){const f=state.analyticsFilter||{period:state.settings.analyticsPeriod||"month",department:"",employeeId:""},end=safeDate(f.end)||new Date();end.setHours(23,59,59,999);let start;if(f.month){start=new Date(`${f.month}-01T00:00:00`);end.setTime(new Date(start.getFullYear(),start.getMonth()+1,0,23,59,59,999).getTime())}else if(f.start){start=new Date(`${f.start}T00:00:00`)}else{start=new Date(end);const days={week:6,month:29,quarter:91,six_months:183,year:365}[f.period];if(Number.isFinite(days))start.setDate(start.getDate()-days);else start=new Date("2000-01-01T00:00:00")}return {f,start,end};}
function taskWasLate(task){return task.workflow==="Выполнено"&&safeDate(task.completedAt)&&safeDate(task.deadline)&&safeDate(task.completedAt)>safeDate(task.deadline)}
function analyticsData(){const {f,start,end}=analyticsBounds();return state.tasks.filter(t=>{const created=safeDate(t.createdAt);return created&&created>=start&&created<=end&&(!f.department||t.department===f.department)});}
function employeeMetrics(employee,list){const assigned=list.filter(t=>t.assignees.includes(employee.id)),done=assigned.filter(t=>t.workflow==="Выполнено"),overdue=assigned.filter(t=>isOverdue(t)||taskWasLate(t)),onTime=done.filter(t=>!taskWasLate(t));const percent=assigned.length?Math.round(done.length*100/assigned.length):0,onTimePercent=assigned.length?Math.round(onTime.length*100/assigned.length):0,overduePercent=assigned.length?Math.round(overdue.length*100/assigned.length):0;let recommendation="Сохранять текущий ритм и контролировать сроки.";if(overduePercent>Number(state.settings.overdueThreshold||20))recommendation="Обсудить причины просрочек и скорректировать нагрузку.";else if(onTimePercent>Number(state.settings.highResultThreshold||80))recommendation="Высокая результативность: можно расширить зону ответственности.";const weeks=Array.from({length:4},(_,index)=>{const end=new Date(analyticsBounds().end);end.setDate(end.getDate()-(3-index)*7);const start=new Date(end);start.setDate(start.getDate()-6);return {label:`${formatDate(start,{day:"2-digit",month:"2-digit"})}–${formatDate(end,{day:"2-digit",month:"2-digit"})}`,completed:done.filter(t=>{const d=safeDate(t.completedAt);return d&&d>=start&&d<=end}).length,overdue:overdue.filter(t=>{const d=safeDate(t.completedAt)||safeDate(t.deadline);return d&&d>=start&&d<=end}).length}});return {employee,assigned,done:done.length,active:assigned.length-done.length,overdue:overdue.length,onTime:onTime.length,percent,onTimePercent,overduePercent,recommendation,weeks};}
function analytics(){const departments=[...new Set(state.employees.filter(e=>!e.archived).map(e=>e.department))],{f,start,end}=analyticsBounds(),list=analyticsData(),selectedEmployee=person(f.employeeId);const summary=departments.filter(d=>!f.department||d===f.department).map(name=>{const tasks=list.filter(t=>t.department===name),completed=tasks.filter(t=>t.workflow==="Выполнено").length,overdue=tasks.filter(t=>isOverdue(t)||taskWasLate(t)).length;return{name,total:tasks.length,completed,active:tasks.length-completed,overdue,percent:tasks.length?Math.round(completed*100/tasks.length):0}});const ranking=state.employees.filter(e=>!e.archived&&(!f.department||e.department===f.department)).map(e=>employeeMetrics(e,list)).sort((a,b)=>b.done-a.done||b.percent-a.percent);const profile=selectedEmployee?employeeMetrics(selectedEmployee,list):null;app.innerHTML=header("Для руководства","Аналитика",`Сводка за период ${formatDate(start)} — ${formatDate(end)}.`,`<div class="form-actions"><button class="button ghost" data-action="print-analytics">Распечатать</button><button class="button secondary" data-action="export-analytics">Сводка CSV</button></div>`)+`
  <section class="panel analytics-filter"><label>Быстрый период<select id="analyticsPeriod">${[["week","Неделя"],["month","Месяц"],["quarter","Квартал"],["six_months","Полгода"],["year","Год"],["all","Всё время"]].map(([v,l])=>`<option value="${v}" ${f.period===v&&!f.month&&!f.start?"selected":""}>${l}</option>`).join("")}</select></label><label>Конкретный месяц<input id="analyticsMonth" type="month" value="${esc(f.month||"")}"></label><label>С<input id="analyticsStart" type="date" value="${esc(f.start||"")}"></label><label>По<input id="analyticsEnd" type="date" value="${esc(f.end||"")}"></label><label>Отдел<select id="analyticsDepartment"><option value="">Все отделы</option>${departments.map(d=>`<option ${f.department===d?"selected":""}>${esc(d)}</option>`).join("")}</select></label><label>Профиль сотрудника<select id="analyticsEmployee"><option value="">Выберите сотрудника</option>${state.employees.filter(e=>!e.archived).map(e=>`<option value="${e.id}" ${Number(f.employeeId)===e.id?"selected":""}>${esc(e.name)}</option>`).join("")}</select></label><button class="button" data-action="apply-analytics">Показать</button></section>
  <section class="stats-grid"><div class="stat-card"><span>Всего задач</span><strong>${list.length}</strong></div><div class="stat-card success"><span>Выполнено</span><strong>${list.filter(t=>t.workflow==="Выполнено").length}</strong></div><div class="stat-card danger"><span>Просрочено</span><strong>${list.filter(t=>isOverdue(t)||taskWasLate(t)).length}</strong></div></section>
  <section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Отдел</th><th>Всего задач</th><th>Выполнено</th><th>В работе</th><th>Просрочено</th></tr></thead><tbody>${summary.map(item=>`<tr><td><strong>${esc(item.name)}</strong></td><td>${item.total}</td><td>${item.completed}</td><td>${item.active}</td><td>${item.overdue}</td></tr>`).join("")}</tbody></table></div></section>
  <section class="panel analytics-chart"><h2>Задачи по отделам</h2><div class="department-bars">${summary.map(item=>`<div><strong>${esc(item.name)}</strong><span>Выполнено ${item.completed}</span><i><b style="width:${item.percent}%"></b></i><span>В работе ${item.active} · Просрочено ${item.overdue}</span></div>`).join("")}</div></section>
  ${profile?`<section class="panel efficiency-profile"><div class="profile-overview">${avatar(profile.employee,"profile-photo profile-placeholder")}<div><span class="eyebrow">Профиль за выбранный период</span><h2>${esc(profile.employee.name)}</h2><p>${esc(profile.employee.department)} · ${esc(profile.employee.status)}</p></div></div><div class="stats-grid"><div class="stat-card"><span>Всего задач</span><strong>${profile.assigned.length}</strong></div><div class="stat-card success"><span>Выполнено в срок</span><strong>${profile.onTime}</strong><small>${profile.onTimePercent}%</small></div><div class="stat-card danger"><span>Просрочено</span><strong>${profile.overdue}</strong><small>${profile.overduePercent}%</small></div></div><div class="recommendation"><strong>Рекомендация</strong><p>${esc(profile.recommendation)}</p></div><h3>Распределение по должностям</h3><div class="week-dynamics"><div><strong>${esc(profile.employee.position)}</strong><span>Основная должность · 1 ставка</span><span>Выполнено задач: ${profile.done}</span></div></div><h3>Динамика за последние 4 недели периода</h3><div class="week-dynamics">${profile.weeks.map(w=>`<div><strong>${w.label}</strong><span>Выполнено: ${w.completed}</span><span>Просрочено: ${w.overdue}</span></div>`).join("")}</div></section>`:""}
  <section class="panel analytics-ranking"><div class="section-heading"><div><span class="eyebrow">Выбранный период</span><h2>Дашборд и рейтинг сотрудников</h2></div></div><div class="employee-metric-grid">${ranking.map((item,index)=>`<button data-action="employee-analytics" data-id="${item.employee.id}"><span class="rank-number">${index+1}</span><span class="metric-donut" style="--metric:${item.percent}"><b>${item.percent}%</b></span><strong>${esc(item.employee.name)}</strong><span>Выполнено ${item.done}</span><span>Просрочено ${item.overdue}</span><small>Открыть подробный профиль</small></button>`).join("")||empty("Нет сотрудников для выбранного фильтра")}</div></section>
  <section class="panel task-extra"><span class="eyebrow">Сохранённые</span><h2>Недельные отчёты сотрудников</h2><p class="muted">В демоверсии отчёты рассчитываются интерактивно и не содержат серверных файлов.</p></section>`;}

function notifications(){const list=state.notifications.filter(n=>n.recipient===state.currentEmployee);openModal(`<div class="modal-content"><div class="section-heading"><div><span class="eyebrow">${esc(current().name)}</span><h2>Уведомления</h2></div><button class="text-link" data-action="read-all">Прочитать все</button></div><div class="notification-list">${list.map(n=>`<a class="notification-item ${n.read?"":"unread"}" href="${esc(n.link||"#overview")}" data-action="open-notification" data-id="${n.id}"><span class="notification-icon">i</span><span><strong>${esc(n.text)}</strong><small>${formatDateTime(n.createdAt)}</small></span>${n.read?"":"<i></i>"}</a>`).join("")||empty("Уведомлений нет")}</div></div>`)}
function profile(){const e=current(),session=workSession(),mine=state.tasks.filter(task=>task.assignees.includes(e.id)&&task.workflow!=="Выполнено").sort((a,b)=>new Date(a.deadline)-new Date(b.deadline));openModal(`<div class="modal-content profile-dialog"><div class="profile-overview">${avatar(e,"profile-photo profile-placeholder")}<div class="profile-summary"><span class="eyebrow">Личный профиль</span><h2>${esc(e.name)}</h2><span class="presence-label">${esc(e.status)}${e.absenceFrom?` · ${formatDate(e.absenceFrom)}–${formatDate(e.absenceTo)}`:""}</span></div></div><dl class="profile-facts"><div><dt>Отдел</dt><dd>${esc(e.department)}</dd></div><div><dt>Должность</dt><dd>${esc(e.position)}</dd></div><div><dt>Дата рождения / возраст</dt><dd>${formatDate(e.birthDate)} · ${age(e.birthDate)}</dd></div><div><dt>Свободные окна</dt><dd>${esc(e.freeSlots||"Не указаны")}</dd></div>${e.photoName?`<div><dt>Фотография</dt><dd>${esc(e.photoName)}</dd></div>`:""}</dl><section class="workday-panel"><div><span class="eyebrow">Рабочий день</span><strong id="workTimer">${session?elapsed(session):"00:00:00"}</strong><small>${session?`Таймер включён с ${formatDateTime(session.startedAt)}`:"Таймер ещё не включён"}</small></div><button class="button ${session?"danger":"secondary"}" data-action="toggle-workday">${session?"Выключить":"Включить"} таймер</button></section><details open><summary>Изменить личные данные</summary><form id="profileForm" class="form-grid"><label class="field"><span>Фотография</span><input type="file" name="photo" accept=".png,.jpg,.jpeg,.gif,.webp"></label><label class="field"><span>Статус присутствия</span><select name="status">${catalogEntries("presenceStatuses").map(item=>`<option ${e.status===item.name?"selected":""}>${esc(item.name)}</option>`).join("")}</select></label><label class="field"><span>Отсутствие с</span><input type="date" name="absenceFrom" value="${esc(e.absenceFrom)}"></label><label class="field"><span>Отсутствие по</span><input type="date" name="absenceTo" value="${esc(e.absenceTo)}"></label><label class="field field-wide"><span>Свободные слоты для встреч</span><textarea name="freeSlots" rows="2">${esc(e.freeSlots)}</textarea></label><button class="button">Сохранить профиль</button></form></details><section class="task-materials"><div class="section-heading"><div><span class="eyebrow">Личная работа</span><h3>Мои задачи</h3></div><button class="button secondary" data-action="weekly-report">Отчёт за неделю</button></div>${mine.map(task=>`<a class="compact-task" href="#tasks/${task.id}" data-action="close-modal"><span class="status-dot"></span><span class="compact-task-body"><strong>${esc(task.title)}</strong><small>${esc(task.department)} · ${esc(task.workflow)}</small></span><span class="compact-deadline">${formatDateTime(task.deadline)}</span></a>`).join("")||empty("Задач нет")}</section><details><summary>Переключить демо-профиль</summary><p class="muted">Переключение имитирует вход и не является серверной защитой.</p><div class="profile-list">${state.employees.filter(item=>!item.archived).map(item=>`<button class="profile-choice chat-room ${item.id===state.currentEmployee?"active":""}" data-action="select-employee" data-id="${item.id}">${avatar(item,"avatar")}<span><strong>${esc(item.name)}</strong><small>${esc(item.position)} · ${esc(roleLabels[item.role])}</small></span></button>`).join("")}</div></details></div>`)}
function weeklyReport(){const e=current(),start=new Date();start.setDate(start.getDate()-7);const assigned=state.tasks.filter(task=>task.assignees.includes(e.id)),completed=assigned.filter(task=>task.workflow==="Выполнено"&&safeDate(task.completedAt||task.deadline)>=start),active=assigned.filter(task=>task.workflow!=="Выполнено"),overdue=active.filter(isOverdue);openModal(`<div class="modal-content"><span class="eyebrow">Личный отчёт · последние 7 дней</span><h2>${esc(e.name)}</h2><p>${esc(e.department)} · сформирован ${formatDateTime(nowIso())}</p><section class="task-materials"><h3>Выполнено за неделю</h3>${completed.map(task=>`<p><strong>${esc(task.title)}</strong> · ${formatDateTime(task.completedAt)}</p>`).join("")||`<p class="muted">Нет задач.</p>`}</section><section class="task-materials"><h3>В работе</h3>${active.map(task=>`<p><strong>${esc(task.title)}</strong> · срок ${formatDateTime(task.deadline)}</p>`).join("")||`<p class="muted">Нет задач.</p>`}</section><section class="task-materials"><h3>Просрочено</h3>${overdue.map(task=>`<p><strong>${esc(task.title)}</strong> · причина: ${esc(task.overdueReason||"не указана")}</p>`).join("")||`<p class="muted">Нет просроченных задач.</p>`}</section></div>`)}
function openModal(html){modalBody.innerHTML=html;if(!modal.open)modal.showModal();}
function closeModal(){if(modal.open)modal.close();modalBody.innerHTML="";if(route().name==="tasks"&&route().id)history.replaceState(null,"", "#tasks");}
function validHttp(value){if(!value)return true;try{return ["http:","https:"].includes(new URL(value).protocol)}catch{return false}}
function downloadCsv(name,rows){const csv="\ufeff"+rows.map(row=>row.map(value=>`"${String(value??"").replaceAll('"','""')}"`).join(";")).join("\r\n");const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0)}
function exportTasks(){const list=route().name==="completed"?visibleTasks(true):visibleTasks(false);downloadCsv("pioneer-tasks-demo.csv",[["Номер отдела","Задача","Описание","Отдел","Исполнители","Наблюдатели","Согласующий 1","Согласующий 2","Приоритет","Создано","Дедлайн","Статус"],...list.map(t=>[t.departmentNumber||t.id,t.title,t.description,t.department,t.assignees.map(id=>person(id)?.name).join(", "),t.observers.map(id=>person(id)?.name).join(", "),person(t.approvers[0])?.name,person(t.approvers[1])?.name,t.priority,t.createdAt,t.deadline,t.workflow])])}
function exportAnalytics(){const list=analyticsData();downloadCsv("pioneer-analytics-demo.csv",[["ID","Задача","Отдел","Статус","Просрочено","Исполнители","Создано","Дедлайн"],...list.map(t=>[t.id,t.title,t.department,t.workflow,isOverdue(t)?"Да":"Нет",t.assignees.map(id=>person(id)?.name).join(", "),t.createdAt,t.deadline])])}
function autoSubstitute(employee){if(!absentStatuses.has(employee.status)||!employee.substitute)return 0;let count=0;state.tasks.filter(t=>t.workflow!=="Выполнено").forEach(t=>{for(const role of ["assignees","observers","approvers"]){if(!t[role].includes(employee.id)||t[role].includes(employee.substitute))continue;t[role]=t[role].map(id=>id===employee.id?employee.substitute:id);t.substitutions??=[];t.substitutions.push({role,original:employee.id,replacement:employee.substitute,active:true,at:nowIso()});if(role==="approvers")t.decisions={};t.history.push({at:nowIso(),actor:state.currentEmployee,text:`Автозамена (${roleLabel(role)}): ${employee.name} → ${person(employee.substitute)?.name}. Причина: ${employee.status}`});addNotification(employee.substitute,`Вы автоматически назначены в задачу «${t.title}» на период отсутствия коллеги`,`#tasks/${t.id}`);count++}});return count;}
function restoreSubstitutions(employee){let count=0;state.tasks.filter(t=>t.workflow!=="Выполнено").forEach(t=>(t.substitutions||[]).filter(s=>s.active&&s.original===employee.id).forEach(s=>{t[s.role]=t[s.role].map(id=>id===s.replacement?employee.id:id);s.active=false;t.history.push({at:nowIso(),actor:state.currentEmployee,text:`Возврат участника (${roleLabel(s.role)}): ${person(s.replacement)?.name} → ${employee.name}`});count++}));return count;}
function roleLabel(role){return {assignees:"исполнитель",observers:"наблюдатель",approvers:"согласующий"}[role]||role;}

document.addEventListener("submit",event=>{
  const form=event.target;if(!form.matches("form"))return;event.preventDefault();const data=new FormData(form);
  if(form.id==="taskForm"){const approvers=[Number(data.get("approver1")),Number(data.get("approver2"))],assignees=selected(form,"assignees");if(approvers[0]===approvers[1])return $("#taskFormError").textContent="Нужны ровно два разных согласующих.";if(!assignees.length)return $("#taskFormError").textContent="Выберите хотя бы одного исполнителя.";const id=Math.max(0,...state.tasks.map(task=>Number(task.id)||0))+1,department=data.get("department"),departmentNumber=Math.max(0,...state.tasks.filter(task=>task.department===department).map(task=>Number(task.departmentNumber)||0))+1,observers=selected(form,"observers");const task={id,departmentNumber,title:data.get("title").trim(),description:data.get("description").trim(),department,assignees,observers,approvers,creator:state.currentEmployee,priority:data.get("priority"),createdAt:nowIso(),deadline:data.get("deadline"),workflow:"Новая",decisions:{},comments:[],results:[],substitutions:[],history:[{at:nowIso(),actor:state.currentEmployee,text:`Задача № ${departmentNumber} создана. Исполнители: ${assignees.map(id=>person(id)?.name).join(", ")}. Наблюдатели: ${observers.map(id=>person(id)?.name).join(", ")||"нет"}. Согласующие: ${approvers.map(id=>person(id)?.name).join(", ")}`}]};state.tasks.unshift(task);assignees.forEach(user=>addNotification(user,`Вы назначены исполнителем задачи № ${departmentNumber} «${task.title}»`,`#tasks/${id}`));observers.forEach(user=>addNotification(user,`Вы назначены наблюдателем задачи № ${departmentNumber} «${task.title}»`,`#tasks/${id}`));approvers.forEach(user=>addNotification(user,`Вы назначены согласующим задачи № ${departmentNumber} «${task.title}»`,`#tasks/${id}`));save();closeModal();location.hash=`tasks/${id}`;render();toast("Задача создана");}
  if(form.id==="taskCommentForm"){const task=state.tasks.find(t=>t.id===Number(form.dataset.id));task.comments.push({id:Date.now(),author:state.currentEmployee,text:data.get("text").trim(),createdAt:nowIso()});save();taskDialog(task.id);}
  if(form.id==="replacementForm"){const task=state.tasks.find(t=>t.id===Number(form.dataset.id)),role=data.get("role"),from=Number(data.get("from")),to=Number(data.get("to"));if(current().role==="employee"&&!task.approvers.includes(state.currentEmployee))return toast("У выбранного профиля нет права менять участников");if(!["assignees","observers","approvers"].includes(role)||!task[role].includes(from))return toast("Выберите участника указанной роли");if(!to||from===to||task[role].includes(to))return toast("Выберите другого сотрудника, которого ещё нет в этой роли");task[role]=task[role].map(id=>id===from?to:id);if(role==="approvers")task.decisions={};task.history.push({at:nowIso(),actor:state.currentEmployee,text:`Ручная замена (${roleLabel(role)}): ${person(from)?.name} → ${person(to)?.name}. Причина: ${data.get("reason")}`});addNotification(to,`Вы назначены в задачу «${task.title}» после ручной замены`,`#tasks/${task.id}`);addNotification(from,`Ваша роль в задаче «${task.title}» передана другому сотруднику`,`#tasks/${task.id}`);save();taskDialog(task.id);toast("Замена сохранена в истории");}
  if(form.id==="meetingForm"){const start=data.get("start"),end=data.get("end"),date=data.get("date"),link=data.get("link").trim();if(start>=end)return $("#meetingFormError").textContent="Окончание должно быть позже начала.";if(!validHttp(link))return $("#meetingFormError").textContent="Разрешены только ссылки HTTP(S).";const participants=selected(form,"participants");if(!participants.length)return $("#meetingFormError").textContent="Выберите участников.";const meeting={id:Date.now(),title:data.get("title").trim(),date,start,end,type:data.get("type"),participants,organizer:state.currentEmployee,link,notes:data.get("notes").trim(),status:"Запланирована",createdAt:nowIso()};state.meetings.push(meeting);participants.forEach(id=>id!==state.currentEmployee&&addNotification(id,`Встреча «${meeting.title}» назначена на ${formatDate(date)} ${start}`,"#calendar"));save();closeModal();render();toast("Встреча добавлена. Помещение при необходимости бронируется отдельно");}
  if(form.id==="bookingForm"){const roomId=Number(data.get("roomId")),date=data.get("date"),startHour=Number(data.get("startHour")),endHour=Number(data.get("endHour")),departments=selectedValues(form,"departments"),responsibles=selected(form,"responsibles");if(!can("rooms")&&roomById(roomId)?.responsible!==state.currentEmployee)return $("#bookingFormError").textContent="Нет права бронировать это помещение.";if(startHour>=endHour)return $("#bookingFormError").textContent="Окончание должно быть позже начала.";if(!departments.length||!responsibles.length)return $("#bookingFormError").textContent="Выберите отдел и ответственного.";const overlap=state.roomBookings.some(item=>item.status==="Активна"&&item.roomId===roomId&&item.date===date&&startHour<item.endHour&&endHour>item.startHour);if(overlap)return $("#bookingFormError").textContent="Помещение уже занято в выбранный интервал.";const booking={id:Date.now(),roomId,date,startHour,endHour,title:data.get("title").trim(),departments,responsibles,creator:state.currentEmployee,status:"Активна",createdAt:nowIso()};state.roomBookings.push(booking);responsibles.filter(id=>id!==state.currentEmployee).forEach(id=>addNotification(id,`Вы ответственный за бронь «${booking.title}»`,"#calendar"));save();calendar();toast("Помещение забронировано");}
  if(form.id==="taskResultForm"){const task=state.tasks.find(item=>item.id===Number(form.dataset.id)),file=form.elements.attachment.files[0];if(!task.assignees.includes(state.currentEmployee))return toast("Только исполнитель может отправить результат");const version=(task.results||[]).length+1;task.results??=[];task.overdueReason=data.get("overdueReason")?.trim()||task.overdueReason||"";task.results.push({id:Date.now(),author:state.currentEmployee,comment:data.get("comment").trim(),attachment:file?.name||"",version,createdAt:nowIso()});task.workflow="На проверке";task.decisions={};task.latestRevision=null;task.history.push({at:nowIso(),actor:state.currentEmployee,text:`Результат версии ${version} отправлен на согласование${file?`: ${file.name}`:""}${task.overdueReason?`. Причина просрочки: ${task.overdueReason}`:""}`});task.approvers.forEach(id=>addNotification(id,`Задача «${task.title}» ожидает вашего решения`,`#tasks/${task.id}`));save();taskDialog(task.id);toast("Результат отправлен на согласование");}
  if(form.id==="deadlineForm"){const task=state.tasks.find(item=>item.id===Number(form.dataset.id)),previous=task.deadline;task.deadline=data.get("deadline");task.history.push({at:nowIso(),actor:state.currentEmployee,text:`Дедлайн изменён: ${formatDateTime(previous)} → ${formatDateTime(task.deadline)}. ${data.get("reason")}`});new Set([...task.assignees,...task.observers]).forEach(id=>addNotification(id,`Изменён срок задачи «${task.title}»`,`#tasks/${task.id}`));save();taskDialog(task.id);toast("Дедлайн обновлён");}
  if(form.id==="extensionForm"){const task=state.tasks.find(item=>item.id===Number(form.dataset.id));task.history.push({at:nowIso(),actor:state.currentEmployee,text:`Запрос продления до ${formatDateTime(data.get("deadline"))}: ${data.get("reason")}`});addNotification(task.creator,`Запрошено продление задачи «${task.title}»`,`#tasks/${task.id}`);save();taskDialog(task.id);toast("Запрос продления отправлен автору");}
  if(form.id==="messageForm"){const chat=state.chats.find(c=>c.id===Number(form.dataset.id)),file=form.elements.attachment.files[0],text=data.get("text").trim();if(!text&&!file)return toast("Введите сообщение или выберите файл");chat.messages.push({id:Date.now(),author:state.currentEmployee,text,createdAt:nowIso(),attachment:file?.name||"",readBy:[]});chat.members.filter(id=>id!==state.currentEmployee).forEach(id=>addNotification(id,`Новое сообщение в «${chat.name}»`,"#messages"));save();messages();}
  if(form.id==="callLinkForm"){const chat=state.chats.find(c=>c.id===Number(form.dataset.id)),link=data.get("link").trim();if(chat.creator!==state.currentEmployee)return toast("Ссылку звонка может менять только создатель беседы");if(!validHttp(link))return toast("Нужна корректная ссылка HTTP(S)");chat.callLink=link;save();messages();toast("Ссылка сохранена");}
  if(form.id==="chatForm"){const members=selected(form,"members"),kind=data.get("kind");if(kind==="private"&&members.length!==1)return $("#chatFormError").textContent="Для личной беседы выберите одного коллегу.";if(!members.length)return $("#chatFormError").textContent="Выберите участников.";if(kind==="private"&&state.chats.some(chat=>chat.kind==="private"&&chat.members.length===2&&chat.members.includes(state.currentEmployee)&&chat.members.includes(members[0])))return $("#chatFormError").textContent="Личная беседа с этим сотрудником уже существует.";const chat={id:Date.now(),creator:state.currentEmployee,name:data.get("name").trim(),kind,members:[state.currentEmployee,...members],callLink:"",messages:[]};state.chats.push(chat);state.activeChat=chat.id;save();closeModal();messages();}
  if(form.id==="employeeForm"){const editId=Number(form.dataset.id),email=data.get("email").trim().toLowerCase();if(!can("employees_admin"))return toast("У выбранного профиля нет права управления сотрудниками");if(state.employees.some(e=>e.email?.toLowerCase()===email&&e.id!==editId))return $("#employeeFormError").textContent="Этот email уже используется.";if(data.get("absenceFrom")&&data.get("absenceTo")&&data.get("absenceFrom")>data.get("absenceTo"))return $("#employeeFormError").textContent="Проверьте период отсутствия.";const values={name:data.get("name").trim(),department:data.get("department").trim(),position:data.get("position").trim(),email,birthDate:data.get("birthDate"),role:data.get("role"),status:data.get("status"),departmentHead:Number(data.get("departmentHead"))||null,substitute:Number(data.get("substitute"))||null,freeSlots:data.get("freeSlots").trim(),absenceFrom:data.get("absenceFrom"),absenceTo:data.get("absenceTo")};let target,returned=0;if(editId){target=person(editId);const wasAbsent=absentStatuses.has(target.status);Object.assign(target,values);if(wasAbsent&&!absentStatuses.has(target.status))returned=restoreSubstitutions(target)}else{target={id:Date.now(),...values,archived:false};state.employees.push(target)}const replacements=autoSubstitute(target);save();closeModal();employees();toast(replacements?`Сотрудник сохранён. Автозамен: ${replacements}`:returned?`Сотрудник вернулся. Восстановлено ролей: ${returned}`:"Сотрудник сохранён");}
  if(form.id==="dismissalForm"){if(!can("employees_admin"))return toast("Недостаточно прав");const employee=person(Number(form.dataset.id)),reason=data.get("reason").trim(),replacements={assignees:Number(data.get("assignee")),observers:Number(data.get("observer")),approvers:Number(data.get("approver"))};let count=0;state.tasks.filter(task=>task.workflow!=="Выполнено").forEach(task=>{for(const [role,replacement] of Object.entries(replacements)){if(!task[role].includes(employee.id))continue;task[role]=[...new Set(task[role].map(id=>id===employee.id?replacement:id))];task.substitutions??=[];task.substitutions.push({role,original:employee.id,replacement,active:true,source:"dismissal",reason,at:nowIso()});task.history.push({at:nowIso(),actor:state.currentEmployee,text:`Передача при увольнении (${roleLabel(role)}): ${employee.name} → ${person(replacement)?.name}. Причина: ${reason}`});addNotification(replacement,`Вам передана роль в задаче «${task.title}» после увольнения коллеги`,`#tasks/${task.id}`);count++}if(task.creator===employee.id)task.creator=replacements.assignees});const newHead=Number(data.get("departmentHead"));state.employees.forEach(item=>{if(item.departmentHead===employee.id)item.departmentHead=newHead||null;if(item.substitute===employee.id)item.substitute=null});employee.archived=true;employee.dismissedAt=nowIso();employee.dismissalReason=reason;employee.status="🔴 Не в сети";state.posts.unshift({id:Date.now(),author:state.currentEmployee,type:"Важное объявление",audience:"all",text:`${employee.name} больше не работает в организации.`,attachments:[],createdAt:nowIso(),reactions:{like:[],support:[],important:[],thanks:[]},comments:[]});save();closeModal();employees();toast(`Сотрудник перемещён в архив. Передано ролей: ${count}`);}
  if(form.id==="profileForm"){const e=current(),status=data.get("status"),from=data.get("absenceFrom"),to=data.get("absenceTo"),wasAbsent=absentStatuses.has(e.status);if(absentStatuses.has(status)&&(!from||!to))return toast("Для отсутствия укажите обе даты");if(from&&to&&from>to)return toast("Проверьте период отсутствия");e.status=status;e.absenceFrom=absentStatuses.has(status)?from:"";e.absenceTo=absentStatuses.has(status)?to:"";e.freeSlots=data.get("freeSlots").trim();e.photoName=form.elements.photo.files[0]?.name||e.photoName||"";const returned=wasAbsent&&!absentStatuses.has(status)?restoreSubstitutions(e):0,replacements=autoSubstitute(e);save();profile();toast(replacements?`Профиль сохранён. Автозамен: ${replacements}`:returned?`Профиль сохранён. Восстановлено ролей: ${returned}`:"Профиль сохранён");}
  if(form.id==="postForm"){if(!can("news"))return toast("У выбранного профиля нет права публиковать новости");const id=Number(form.dataset.id),post=state.posts.find(p=>p.id===id),files=[...form.elements.attachments.files].map(file=>file.name);if(post&&post.author!==state.currentEmployee)return toast("Редактировать публикацию может только её автор");if(post){post.type=data.get("type");post.audience=data.get("audience");post.text=data.get("text").trim();if(files.length)post.attachments=[...(post.attachments||[]),...files];post.editedAt=nowIso()}else state.posts.unshift({id:Date.now(),author:state.currentEmployee,type:data.get("type"),audience:data.get("audience"),text:data.get("text").trim(),attachments:files,createdAt:nowIso(),reactions:{like:[],support:[],important:[],thanks:[]},comments:[]});save();closeModal();feed();toast("Публикация сохранена");}
  if(form.matches("[data-post-id]")){const post=state.posts.find(p=>p.id===Number(form.dataset.postId)),file=form.elements.attachment.files[0],text=data.get("text").trim();if(!text&&!file)return toast("Введите комментарий или выберите файл");post.comments.push({id:Date.now(),author:state.currentEmployee,text,attachment:file?.name||"",createdAt:nowIso()});save();feed();}
  if(form.id==="settingsForm"){if(!can("settings"))return toast("Недостаточно прав");if(data.get("workStart")>=data.get("workEnd"))return toast("Окончание рабочего дня должно быть позже начала");Object.assign(state.settings,{portalName:data.get("portalName").trim()||"ПИОНЕР",color:data.get("color"),sound:data.get("sound")==="on",workStart:data.get("workStart"),workEnd:data.get("workEnd"),weekends:data.get("weekends").trim(),analyticsPeriod:data.get("analyticsPeriod"),highResultThreshold:Number(data.get("highResultThreshold")),overdueThreshold:Number(data.get("overdueThreshold")),sickDaysThreshold:Number(data.get("sickDaysThreshold")),logoName:form.elements.logo.files[0]?.name||state.settings.logoName||""});save();settings();toast("Общие параметры сохранены");}
  if(form.id==="rightsForm"){if(!["director","admin"].includes(current().role))return toast("Изменять права может только директор или администратор");state.employees.filter(e=>!e.archived).forEach(e=>{e.role=data.get(`role_${e.id}`);e.substitute=Number(data.get(`substitute_${e.id}`))||null;state.accessRights[e.id]={};features.forEach(feature=>state.accessRights[e.id][feature]=data.get(`${feature}_${e.id}`)==="on")});save();settings();toast("Роли и права сохранены");}
  if(form.matches(".catalog-entry")){if(!can("settings"))return toast("Недостаточно прав");const entries=catalogEntries(form.dataset.catalog),entry=entries[Number(form.dataset.index)],oldName=entry.name,newName=data.get("name").trim();if(entries.some((item,index)=>index!==Number(form.dataset.index)&&item.name.toLowerCase()===newName.toLowerCase()))return toast("Такое значение уже существует");Object.assign(entry,{name:newName,color:data.get("color"),icon:data.get("icon").trim()||"•"});if(form.dataset.catalog==="rooms")entry.responsible=Number(data.get("responsible"))||null;if(oldName!==newName){if(form.dataset.catalog==="departments"){state.employees.forEach(e=>{if(e.department===oldName)e.department=newName});state.tasks.forEach(t=>{if(t.department===oldName)t.department=newName});state.posts.forEach(p=>{if(p.audience===oldName)p.audience=newName})}if(form.dataset.catalog==="positions")state.employees.forEach(e=>{if(e.position===oldName)e.position=newName})}save();settings();toast("Значение справочника сохранено");}
  if(form.matches(".catalog-add")){if(!can("settings"))return toast("Недостаточно прав");const entries=catalogEntries(form.dataset.catalog),name=data.get("name").trim();if(entries.some(item=>item.name.toLowerCase()===name.toLowerCase()))return toast("Такое значение уже существует");entries.push(form.dataset.catalog==="rooms"?{id:Date.now(),name,color:data.get("color"),icon:data.get("icon").trim()||"•",responsible:Number(data.get("responsible"))||null}:{name,color:data.get("color"),icon:data.get("icon").trim()||"•"});save();settings();toast("Значение добавлено");}
});

document.addEventListener("click",event=>{const target=event.target.closest("[data-action]");if(!target)return;const action=target.dataset.action,id=Number(target.dataset.id);
  if(action==="close-modal")closeModal();
  if(action==="notifications")notifications(); if(action==="profile")profile(); if(action==="new-task")taskForm(); if(action==="new-meeting")meetingForm(); if(action==="meeting")meetingDialog(id); if(action==="booking")bookingDialog(id); if(action==="new-chat")chatForm(); if(action==="new-employee"&&can("employees_admin"))employeeForm(); if(action==="employee")employeeDialog(id); if(action==="edit-employee"&&can("employees_admin"))employeeForm(id); if(action==="new-post"&&can("news"))postForm();
  if(action==="weekly-report")weeklyReport();
  if(action==="apply-task-filter"){state.taskFilter={status:$("#taskStatusFilter").value,department:$("#taskDepartmentFilter").value,mine:$("#taskMineFilter").checked};save();render()}
  if(action==="export-tasks")exportTasks(); if(action==="export-analytics")exportAnalytics();
  if(action==="export-settings"){downloadCsv("pioneer-settings-demo.csv",[["Сотрудник","Роль","Право","Доступ"],...state.employees.flatMap(e=>features.map(feature=>[e.name,roleLabels[e.role],feature,can(feature,e)?"Да":"Нет"]))])}
  if(action==="apply-analytics"){const start=$("#analyticsStart").value,end=$("#analyticsEnd").value;if(start&&end&&start>end)return toast("Дата начала должна быть не позже даты окончания");state.analyticsFilter={period:$("#analyticsPeriod").value,month:$("#analyticsMonth").value,start,end,department:$("#analyticsDepartment").value,employeeId:$("#analyticsEmployee").value};save();analytics()}
  if(action==="employee-analytics"){state.analyticsFilter={...(state.analyticsFilter||{}),employeeId:id};save();analytics();window.scrollTo({top:0,behavior:"smooth"})}
  if(action==="print-analytics")window.print();
  if(action==="start-task"){const t=state.tasks.find(x=>x.id===id);if(!t.assignees.includes(state.currentEmployee)||t.workflow!=="Новая")return toast("Начать может назначенный исполнитель новой задачи");t.workflow="В работе";t.history.push({at:nowIso(),actor:state.currentEmployee,text:"Исполнитель приступил к задаче"});save();taskDialog(id);toast("Задача переведена в работу");}
  if(action==="submit-result"){const t=state.tasks.find(x=>x.id===id);if(!t.assignees.includes(state.currentEmployee))return toast("Только исполнитель может отправить результат");openModal(`<form class="modal-content" id="taskResultForm" data-id="${id}"><span class="eyebrow">Результат задачи № ${t.departmentNumber||t.id}</span><h2>${esc(t.title)}</h2><label class="field"><span>Комментарий к результату</span><textarea name="comment" maxlength="1000"></textarea></label><label class="field"><span>Файл (в демо сохраняется только имя)</span><input type="file" name="attachment"></label>${isOverdue(t)?`<label class="field"><span>Причина просрочки *</span><textarea name="overdueReason" required></textarea></label>`:""}<p class="muted">После отправки задача перейдёт на согласование. Повторная отправка создаст новую версию результата.</p><div class="form-actions"><button type="button" class="button ghost" data-action="close-modal">Отмена</button><button class="button">Отправить на согласование</button></div></form>`);}
  if(action==="approve-task"){const t=state.tasks.find(x=>x.id===id);if(!t.approvers.includes(state.currentEmployee)||t.workflow!=="На проверке")return toast("Решение недоступно");t.decisions[state.currentEmployee]="approved";t.history.push({at:nowIso(),actor:state.currentEmployee,text:"Согласующий принял результат"});const peer=t.approvers.find(user=>user!==state.currentEmployee);if(peer)addNotification(peer,`${current().name} принял(а) задачу «${t.title}»`,`#tasks/${t.id}`);if(t.approvers.every(user=>t.decisions[user]==="approved")){t.workflow="Выполнено";t.completedAt=nowIso();t.history.push({at:nowIso(),actor:state.currentEmployee,text:"Получены два независимых согласования. Задача закрыта"});new Set([...t.assignees,...t.observers,...t.approvers]).forEach(user=>addNotification(user,`Задача «${t.title}» выполнена`,`#tasks/${t.id}`))}save();taskDialog(id);toast(t.workflow==="Выполнено"?"Получены оба согласования. Задача закрыта":"Решение сохранено");}
  if(action==="revision-task"){const t=state.tasks.find(x=>x.id===id);openModal(`<form class="modal-content" id="revisionForm" data-id="${id}"><span class="eyebrow">Возврат на доработку</span><h2>${esc(t.title)}</h2><label class="field"><span>Комментарий *</span><textarea name="comment" required></textarea></label><label class="field"><span>Новый дедлайн *</span><input type="datetime-local" name="deadline" min="${addDays(0).slice(0,16)}" value="${addDays(2,"17:00")}" required></label><div class="form-actions"><button class="button danger">Вернуть</button></div></form>`);}
  if(action==="close-task"){const t=state.tasks.find(x=>x.id===id);if(!t.approvers.includes(state.currentEmployee))return toast("Закрыть задачу может назначенный согласующий");t.workflow="Выполнено";t.completedAt=nowIso();t.history.push({at:nowIso(),actor:state.currentEmployee,text:`Задача закрыта согласующим ${current().name}`});new Set([...t.assignees,...t.observers,...t.approvers]).forEach(user=>addNotification(user,`Задача «${t.title}» закрыта: ${current().name}`,`#tasks/${t.id}`));save();taskDialog(id);toast("Задача закрыта и перенесена в выполненные");}
  if(action==="change-deadline"){const t=state.tasks.find(x=>x.id===id);if(current().role==="employee")return toast("Менять дедлайн может руководитель или администратор");openModal(`<form class="modal-content" id="deadlineForm" data-id="${id}"><span class="eyebrow">Изменение срока</span><h2>${esc(t.title)}</h2><p>Текущий срок: <strong>${formatDateTime(t.deadline)}</strong></p><label class="field"><span>Новый дедлайн *</span><input type="datetime-local" name="deadline" min="${addDays(0).slice(0,16)}" value="${esc(t.deadline.slice(0,16))}" required></label><label class="field"><span>Причина *</span><textarea name="reason" required maxlength="500"></textarea></label><button class="button">Изменить дедлайн</button></form>`);}
  if(action==="request-extension"){const t=state.tasks.find(x=>x.id===id);openModal(`<form class="modal-content" id="extensionForm" data-id="${id}"><span class="eyebrow">Запрос продления</span><h2>${esc(t.title)}</h2><label class="field"><span>Желаемый дедлайн *</span><input type="datetime-local" name="deadline" min="${addDays(1).slice(0,16)}" value="${addDays(2,"17:00")}" required></label><label class="field"><span>Обоснование *</span><textarea name="reason" required maxlength="500"></textarea></label><button class="button">Отправить запрос</button></form>`);}
  if(action==="delete-task"){const t=state.tasks.find(x=>x.id===id);if(t.creator!==state.currentEmployee||t.workflow!=="Новая")return toast("Удалить можно только свою новую задачу");if(confirm(`Удалить задачу «${t.title}»?`)){state.tasks=state.tasks.filter(item=>item.id!==id);save();closeModal();location.hash="tasks";render();toast("Задача удалена");}}
  if(action==="chat"){state.activeChat=id;save();messages()} if(action==="message-task"){const text=target.dataset.text||"";closeModal();location.hash="tasks";taskForm(text.slice(0,120))}
  if(action==="select-employee"){state.currentEmployee=id;const chats=accessibleChats();state.activeChat=chats[0]?.id||null;save();closeModal();render();toast("Демо-профиль переключён")}
  if(action==="cancel-meeting"){const m=state.meetings.find(x=>x.id===id);if(!m||(m.organizer!==state.currentEmployee&&!can("rooms")))return toast("Отменить встречу может организатор или пользователь с правом помещений");m.status="Отменена";m.participants.forEach(user=>user!==state.currentEmployee&&addNotification(user,`Встреча «${m.title}» отменена`,"#calendar"));save();closeModal();calendar();toast("Встреча отменена")}
  if(action==="calendar-shift"){state.calendarView.startDate=calendarDate(state.calendarView.startDate,Number(target.dataset.days));save();calendar();}
  if(action==="calendar-today"){state.calendarView.startDate=weekStart();save();calendar();}
  if(action==="prefill-booking"){const form=$("#bookingForm");if(!form)return toast("У выбранного профиля нет права бронирования");const date=target.dataset.date,hour=Number(target.dataset.hour);$("#bookingDate").value=date;$("#bookingStart").value=String(hour);$("#bookingForm input[name=title]").focus();}
  if(action==="cancel-booking"){const booking=state.roomBookings.find(item=>item.id===id);if(!booking||!canCancelBooking(booking))return toast("Недостаточно прав для отмены брони");booking.status="Отменена";booking.cancelledAt=nowIso();booking.cancelledBy=state.currentEmployee;booking.responsibles.filter(user=>user!==state.currentEmployee).forEach(user=>addNotification(user,`Бронь «${booking.title}» отменена`,"#calendar"));save();closeModal();calendar();toast("Бронь отменена, интервал снова свободен");}
  if(action==="delete-catalog"){if(!can("settings"))return toast("Недостаточно прав");const key=target.dataset.catalog,index=Number(target.dataset.index),entries=catalogEntries(key),entry=entries[index];const used=key==="departments"&&(state.employees.some(e=>e.department===entry.name)||state.tasks.some(t=>t.department===entry.name))||key==="positions"&&state.employees.some(e=>e.position===entry.name)||key==="rooms"&&state.roomBookings.some(b=>b.roomId===entry.id);if(used)return toast("Значение используется и не может быть удалено");if(confirm(`Удалить «${entry.name}»?`)){entries.splice(index,1);save();settings();toast("Значение удалено")}}
  if(action==="dismiss-employee"){const e=person(id);if(id===state.currentEmployee)return toast("Нельзя архивировать выбранный профиль");const options=employeeOptions([], [id]);openModal(`<form class="modal-content" id="dismissalForm" data-id="${id}"><span class="eyebrow">Увольнение и передача ролей</span><h2>${esc(e.name)}</h2><label class="field"><span>Причина *</span><textarea name="reason" required maxlength="500"></textarea></label><div class="form-grid"><label class="field"><span>Новый исполнитель / автор *</span><select name="assignee" required>${options}</select></label><label class="field"><span>Новый наблюдатель *</span><select name="observer" required>${options}</select></label><label class="field"><span>Новый согласующий *</span><select name="approver" required>${options}</select></label><label class="field"><span>Новый руководитель отдела</span><select name="departmentHead"><option value="">Не назначать</option>${options}</select></label></div><p class="muted">Активные роли будут переданы, сотрудник попадёт в архив, а в общей ленте появится уведомление.</p><button class="button danger">Подтвердить увольнение</button></form>`)}
  if(action==="feed-filter"){state.feedFilter=target.dataset.filter;save();feed()} if(action==="react"){const p=state.posts.find(x=>x.id===id),key=target.dataset.reaction;p.reactions??={};reactions.forEach(([reaction])=>p.reactions[reaction]??=[]);Object.keys(p.reactions).forEach(k=>p.reactions[k]=p.reactions[k].filter(user=>user!==state.currentEmployee));if(!target.classList.contains("active"))p.reactions[key].push(state.currentEmployee);save();feed()}
  if(action==="edit-post")postForm(state.posts.find(p=>p.id===id)); if(action==="delete-post"&&confirm("Удалить эту публикацию?")){state.posts=state.posts.filter(p=>p.id!==id);save();feed()}
  if(action==="read-all"){state.notifications.filter(n=>n.recipient===state.currentEmployee).forEach(n=>n.read=true);save();notifications()} if(action==="open-notification"){const n=state.notifications.find(x=>x.id===id);if(!n)return;n.read=true;save();closeModal();if(n.link)location.hash=n.link.replace(/^#/,"");else render()}
  if(action==="toggle-workday"){const session=workSession();if(session)session.endedAt=nowIso();else state.workdays.push({id:Date.now(),employee:state.currentEmployee,startedAt:nowIso(),endedAt:null});save();if(modal.open)profile();else overview();toast(session?"Рабочий день завершён":"Таймер рабочего дня запущен")}
  if(action==="reset"&&current().role==="admin"&&confirm("Удалить все локальные задачи, сотрудников, сообщения, публикации, встречи, брони и настройки демо?")){localStorage.removeItem(STORAGE_KEY);state=seedState();save();render();toast("Демо-данные сброшены")}
});
document.addEventListener("submit",event=>{if(event.target.id!=="revisionForm")return;event.preventDefault();const form=event.target,data=new FormData(form),t=state.tasks.find(x=>x.id===Number(form.dataset.id));if(!t.approvers.includes(state.currentEmployee)&&current().role==="employee")return toast("Вернуть задачу может согласующий или руководитель");const previousDeadline=t.deadline;t.workflow="На доработке";t.deadline=data.get("deadline");t.latestRevision={author:state.currentEmployee,comment:data.get("comment").trim(),previousDeadline,newDeadline:t.deadline,createdAt:nowIso()};t.decisions={[state.currentEmployee]:"revision"};t.history.push({at:nowIso(),actor:state.currentEmployee,text:`Возврат на доработку: ${data.get("comment")}. Новый дедлайн: ${formatDateTime(t.deadline)}`});t.assignees.forEach(user=>addNotification(user,`Задача «${t.title}» возвращена на доработку`,`#tasks/${t.id}`));save();taskDialog(t.id);toast("Задача возвращена на доработку")});
document.addEventListener("change",event=>{if(event.target.matches("[data-action=quick-status]")){const e=current(),wasAbsent=absentStatuses.has(e.status);e.status=event.target.value;const returned=wasAbsent&&!absentStatuses.has(e.status)?restoreSubstitutions(e):0,count=autoSubstitute(e);save();overview();toast(count?`Статус обновлён. Автозамен: ${count}`:returned?`Статус обновлён. Восстановлено ролей: ${returned}`:"Статус обновлён")}if(event.target.id==="calendarRoom"){state.calendarView.roomId=Number(event.target.value);save();calendar();}if(event.target.id==="demoTheme"){state.settings.theme=event.target.value;save();settings();}if(event.target.matches("#departmentFilter,#employeeStatusFilter,#employeeSort"))filterEmployees();});
document.addEventListener("input",event=>{if(event.target.matches("#employeeSearch"))filterEmployees();});
$("#menuButton").addEventListener("click",()=>{const open=document.body.classList.toggle("menu-open");$("#menuButton").setAttribute("aria-expanded",String(open))});
$("#menuOverlay").addEventListener("click",closeMenu);
modal.addEventListener("click",event=>{if(event.target===modal)closeModal()});
document.addEventListener("keydown",event=>{if(event.key!=="Escape")return;closeMenu();if(modal.open)closeModal()});
window.addEventListener("hashchange",()=>{closeMenu();if(modal.open)closeModal();render()});
setInterval(()=>{const timer=$("#workTimer"),session=workSession();if(timer&&session)timer.textContent=elapsed(session)},1000);
updateShell();render();
